// For eight newcomers the core can have at most 80 red edges. Branch on all legal subsets under this cap. Necessary interval bound: all rows independent below; largest surviving blue cliques from above, after deciding certain edits. At cap or terminal upper=lower. Return unexcluded leaves, not claims of full compatibility.
#[path="ramsey_38_six_screen.rs"]mod screen;use std::io::{self,BufRead};fn search(a:&mut Vec<u32>,ed:&[(usize,usize)],k:usize,st:&mut[u64;6]){st[0]+=1;let mut es:Vec<_>=ed.iter().copied().filter(|&(i,j)|a[i]&a[j]==0&&a[i].count_ones()<7&&a[j].count_ones()<7).collect();if k==0{es.clear()}let mut b=a.clone();for &(i,j) in &es{b[i]|=1<<j;b[j]|=1<<i}let mut sets=vec![0u32];let mut n7=0;for(i,&v)in b.iter().enumerate(){let n=sets.len();for j in 0..n{let s=sets[j];if s&v==0{if s.count_ones()==7{st[1]+=1;return}if s.count_ones()==6{n7+=1}sets.push(s|1<<i)}}}if n7>=120||es.is_empty(){if !screen::bounds(a,&b,7,8){st[2]+=1;return}}else{st[3]+=1}if es.is_empty(){st[4]+=1;println!("{}",a.iter().map(|v|v.to_string()).collect::<Vec<_>>().join(" "));return}let impact=|&(i,j):&(usize,usize)|es.iter().filter(|&&(x,y)|(i==x&&a[j]>>y&1!=0)||(i==y&&a[j]>>x&1!=0)||(j==x&&a[i]>>y&1!=0)||(j==y&&a[i]>>x&1!=0)).count();let t=(0..es.len()).max_by_key(|&i|impact(&es[i])).unwrap();let(i,j)=es.swap_remove(t);search(a,&es,k,st);a[i]|=1<<j;a[j]|=1<<i;search(a,&es,k-1,st);a[i]^=1<<j;a[j]^=1<<i}fn main(){for l in io::stdin().lock().lines(){let mut a:Vec<u32>=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect();let e=a.iter().map(|x|x.count_ones()as usize).sum::<usize>()/2;let mut es=vec![];for i in 0..26{for j in 0..i{if a[i]>>j&1==0&&a[i]&a[j]==0{es.push((i,j))}}}let mut st=[0;6];let cap=std::env::args().nth(1).map(|s|s.parse::<usize>().unwrap()).unwrap_or(80);if e<=cap{search(&mut a,&es,cap-e,&mut st)}eprintln!("{:?}",st)}}
